/* Visual prototype only. No authentication, requests, cookies or storage. */
(()=>{
  'use strict';
  const root=document.querySelector('#content');
  const emailField='<div class="field"><label for="email">E-mail</label><input id="email" name="email" type="email" autocomplete="username" inputmode="email" autocapitalize="none" spellcheck="false" placeholder="voce@exemplo.com" required></div>';
  function render(){
    const view=location.hash.slice(1)||'login';
    if(view==='recover')root.innerHTML=`<span class="form-tag">RECUPERAR ACESSO</span><h2>Vamos ajudar você.</h2><p class="intro">Informe seu e-mail para receber as orientações de recuperação.</p><form data-recover>${emailField}<button class="primary" type="submit">Enviar orientações</button></form><a class="secondary" href="#login">Voltar para entrar</a>`;
    else if(view==='sent')root.innerHTML='<div class="success-symbol" aria-hidden="true">✓</div><h2>Confira seu e-mail</h2><p class="intro" role="status">Se houver uma conta com esse e-mail, você receberá as orientações para recuperar o acesso. Confira também o spam.</p><p class="preview-notice">Demonstração: nenhum e-mail foi enviado.</p><a class="primary" href="#login">Voltar para entrar</a>';
    else if(view==='loading')root.innerHTML='<div class="loading-mark" aria-hidden="true"><img src="../../assets/veconi-symbol.svg" alt=""></div><span class="form-tag">QUASE LÁ</span><h2>Preparando<br>seu ambiente…</h2><p class="intro" role="status" aria-live="polite">Conectando sua conta e conferindo o acesso ao seu negócio.</p><ul class="step-list"><li><span aria-hidden="true">✓</span> Sua conta</li><li><span aria-hidden="true">◌</span> Empresa e espaços autorizados</li><li><span aria-hidden="true">○</span> Dados do aplicativo</li></ul><p class="preview-notice">Prévia de carregamento. Nenhuma sessão real foi iniciada. Uma falha de acesso nunca será apresentada como sucesso.</p><a class="secondary" href="#error">Simular falha recuperável</a><a class="secondary" href="#login">Sair e voltar ao login</a>';
    else if(view==='error')root.innerHTML='<span class="form-tag">PRECISAMOS TENTAR NOVAMENTE</span><h2>Não conseguimos<br>concluir o acesso.</h2><p class="intro" role="alert">A preparação foi interrompida. Seus dados continuam preservados. Verifique a conexão e tente novamente.</p><a class="primary" href="#loading">Tentar novamente</a><a class="secondary" href="#recover">Preciso recuperar meu acesso</a><a class="secondary" href="#login">Sair e voltar ao login</a><details><summary>Detalhes técnicos</summary><p>Exemplo fictício: conexão indisponível durante a preparação. Nenhum dado real foi consultado.</p></details>';
    else if(view==='signup')root.innerHTML=`<span class="form-tag">BEM-VINDO À VECONI</span><h2>Seu negócio,<br>mais completo.</h2><p class="intro">A criação de conta permanece no fluxo atual do aplicativo. Esta prévia valida somente a nova apresentação do acesso.</p><a class="primary" href="#login">Voltar para entrar</a>`;
    else root.innerHTML=`<span class="form-tag">SEU NEGÓCIO, MAIS COMPLETO</span><h2>Bom ter você aqui.</h2><p class="intro">Entre para continuar de onde parou.</p><form data-login>${emailField}<div class="field"><label for="password">Senha</label><div class="password-wrap"><input id="password" name="password" type="password" autocomplete="current-password" placeholder="Sua senha" required><button class="password-toggle" type="button" aria-label="Mostrar senha" aria-pressed="false">◉</button></div></div><div class="recover-row"><a href="#recover">Esqueci minha senha</a></div><div data-error role="alert" hidden></div><button class="primary" type="submit">Entrar <span aria-hidden="true">→</span></button></form><p class="signup">Ainda não tem conta? <a href="#signup">Conhecer a VECONI</a></p>`;
    root.querySelector('.password-toggle')?.addEventListener('click',event=>{const input=root.querySelector('#password'),show=input.type==='password';input.type=show?'text':'password';event.currentTarget.setAttribute('aria-pressed',String(show));event.currentTarget.setAttribute('aria-label',show?'Ocultar senha':'Mostrar senha');});
    root.querySelector('[data-login]')?.addEventListener('submit',event=>{event.preventDefault();if(root.querySelector('#password').value==='erro'){const error=root.querySelector('[data-error]');error.hidden=false;error.className='form-error';error.textContent='Não foi possível entrar. Confira o e-mail e a senha ou recupere seu acesso.';}else location.hash='loading';});
    root.querySelector('[data-recover]')?.addEventListener('submit',event=>{event.preventDefault();location.hash='sent';});
  }
  addEventListener('hashchange',()=>{render();root.focus();});render();
})();
